begin;
create table public.prescriptions (id uuid primary key default gen_random_uuid(), encounter_id uuid not null references public.care_encounters(id) on delete restrict, patient_id uuid not null references public.patients(id) on delete restrict, doctor_provider_id uuid not null references public.providers(id) on delete restrict, status public.prescription_status not null default 'active', instructions text, issued_at timestamptz not null default statement_timestamp());
create table public.prescription_items (id uuid primary key default gen_random_uuid(), prescription_id uuid not null references public.prescriptions(id) on delete restrict, medication_name text not null, strength text, dose text, route text, frequency text, duration_days integer check(duration_days is null or duration_days>0), instructions text);
create table public.patient_medications (id uuid primary key default gen_random_uuid(), patient_id uuid not null references public.patients(id) on delete restrict, prescription_item_id uuid references public.prescription_items(id) on delete restrict, medication_name text not null, dose text, frequency text, start_date date, end_date date, status public.patient_medication_status not null default 'active', created_by_profile_id uuid not null references public.profiles(id) on delete restrict, check(end_date is null or start_date is null or end_date>=start_date));
create table public.medication_schedules (id uuid primary key default gen_random_uuid(), patient_medication_id uuid not null references public.patient_medications(id) on delete restrict, time_of_day time not null, days_of_week smallint[], timezone text not null default 'Asia/Yangon', reminder_enabled boolean not null default true, valid_from date, valid_until date, check(days_of_week is null or days_of_week <@ array[0,1,2,3,4,5,6]::smallint[]), check(valid_until is null or valid_from is null or valid_until>=valid_from));
create table public.medication_events (id uuid primary key default gen_random_uuid(), schedule_id uuid not null references public.medication_schedules(id) on delete restrict, patient_id uuid not null references public.patients(id) on delete restrict, scheduled_at timestamptz not null, status public.medication_event_status not null default 'pending', confirmed_by_profile_id uuid references public.profiles(id) on delete restrict, confirmed_at timestamptz);
create index medication_events_patient_scheduled_idx on public.medication_events(patient_id,scheduled_at);
commit;
